/** Exact PCM of the approved energy-meaty.wav; 48kHz mono, 0.7s. */
const PCM = '';
export function shieldEnergySamples(): Float32Array<ArrayBuffer> {
  const bytes = atob(PCM);
  const samples = new Float32Array(bytes.length / 2);
  for (let i = 0; i < samples.length; i += 1) {
    const value = bytes.charCodeAt(i * 2) | (bytes.charCodeAt(i * 2 + 1) << 8);
    samples[i] = (value >= 32768 ? value - 65536 : value) / 32768;
  }
  return samples;
}
export function shieldEnergyBuffer(context: AudioContext): AudioBuffer {
  const samples = shieldEnergySamples();
  const buffer = context.createBuffer(1, samples.length, 48000);
  buffer.copyToChannel(samples, 0);
  return buffer;
}
